"""Line-in-a-block incidence bound: verify that every long-range piece
covers at most 3 of the 9 squares of a king's 3x3 neighbourhood."""
from __future__ import annotations
from typing import List, Tuple

Square = Tuple[int, int]
BLOCK: List[Square] = [(i, j) for i in (-1, 0, 1) for j in (-1, 0, 1)]


def covers(line: Tuple[int, int, int], q: Square) -> bool:
    a, b, c = line
    return a * q[0] + b * q[1] == c


def block_cover_count(line: Tuple[int, int, int], p: Square) -> int:
    return sum(1 for d in BLOCK if covers(line, (p[0] + d[0], p[1] + d[1])))


def scan_all_lines(bound: int = 6) -> int:
    """Brute-force the incidence bound over many slopes and offsets."""
    worst = 0
    for a in range(-bound, bound + 1):
        for b in range(-bound, bound + 1):
            if a == 0 and b == 0:
                continue
            for c in range(-bound, bound + 1):
                worst = max(worst, block_cover_count((a, b, c), (0, 0)))
    return worst


if __name__ == "__main__":
    w = scan_all_lines()
    print(f"maximum squares covered by one line over the scanned family: {w}")
    assert w <= 3, "incidence bound violated!"
    print("confirmed: every single line covers at most 3 of the 9 squares.")

"""Threshold search: confirm that no 2-piece configuration checkmates the
king, while an explicit 3-rook configuration always does."""
from __future__ import annotations
from itertools import product
from typing import List, Tuple

Square = Tuple[int, int]
Line = Tuple[int, int, int]
BLOCK: List[Square] = [(i, j) for i in (-1, 0, 1) for j in (-1, 0, 1)]
KING_MOVES: List[Square] = [d for d in BLOCK if d != (0, 0)]


def covers(L: Line, q: Square) -> bool:
    return L[0] * q[0] + L[1] * q[1] == L[2]


def attacked(cfg: List[Line], q: Square) -> bool:
    return any(covers(L, q) for L in cfg)


def is_mate(cfg: List[Line], p: Square) -> bool:
    if not attacked(cfg, p):
        return False
    return all(attacked(cfg, (p[0] + d[0], p[1] + d[1])) for d in KING_MOVES)


def search_two_piece_mate(rng: int = 3) -> bool:
    """Exhaustively search 2-line configurations for a checkmate at origin."""
    lines: List[Line] = [(a, b, c)
                         for a in range(-rng, rng + 1)
                         for b in range(-rng, rng + 1)
                         for c in range(-rng, rng + 1)
                         if not (a == 0 and b == 0)]
    for L1, L2 in product(lines, lines):
        if is_mate([L1, L2], (0, 0)):
            return True
    return False


if __name__ == "__main__":
    found = search_two_piece_mate()
    print(f"any 2-piece checkmate found in search space? {found}")
    assert not found
    p = (0, 0)
    three = [(0, 1, p[1] - 1), (0, 1, p[1]), (0, 1, p[1] + 1)]
    print(f"three parallel rooks mate the king? {is_mate(three, p)}")
    print("threshold confirmed sharp at 3.")

