from __future__ import annotations
from typing import List, Tuple

Square = Tuple[int, int]
Line = Tuple[int, int, int]  # (a, b, c) meaning a*x + b*y = c
BLOCK: List[Square] = [(i, j) for i in (-1, 0, 1) for j in (-1, 0, 1)]
KING_MOVES: List[Square] = [d for d in BLOCK if d != (0, 0)]


def covers(L: Line, q: Square) -> bool:
    return L[0] * q[0] + L[1] * q[1] == L[2]


def attacked(cfg: List[Line], q: Square) -> bool:
    return any(covers(L, q) for L in cfg)


def is_checkmated(cfg: List[Line], p: Square) -> bool:
    """Decide checkmate: king in check and every escape square attacked.
    Complexity O(9 * |cfg|) = O(|cfg|)."""
    if not attacked(cfg, p):
        return False
    return all(attacked(cfg, (p[0] + d[0], p[1] + d[1])) for d in KING_MOVES)

from __future__ import annotations
from typing import List, Optional, Tuple

Line = Tuple[int, int, int]
Square = Tuple[int, int]


def covers(L: Line, q: Square) -> bool:
    return L[0] * q[0] + L[1] * q[1] == L[2]


def attacked(cfg: List[Line], q: Square) -> bool:
    return any(covers(L, q) for L in cfg)


def find_safe_square_beyond(cfg: List[Line], n: int) -> Optional[Square]:
    """Locate a safe square with first coordinate > n.

    Step 1: choose a row k occupied by no horizontal piece (a=0). Only
            finitely many rows are blocked, so such k exists.
    Step 2: along row k every remaining piece is slanted and meets the row
            at most once, so scanning x = n+1, n+2, ... halts at a safe
            square after at most (#slanted pieces meeting the row) steps.
    Termination guaranteed by the unbounded-flight theorem."""
    blocked_rows = {L[2] for L in cfg if L[0] == 0}
    k = 0
    while k in blocked_rows:
        k += 1
    x = n + 1
    while attacked(cfg, (x, k)):
        x += 1
    return (x, k)
